var main = tree.current_scene
var H = load("res://tests/helpers/sm11e_m3a_scen.gd")
var n := 0
for b in H.phase().dice_log:
	if typeof(b) == TYPE_DICTIONARY and str(b.get("context", "")) == "to_hit":
		n += 1
		for e in b.get("modifier_ledger", []):
			if str(e.get("effect", "")) == "worsen_bs":
				return "BS worsened by %s" % str(e.get("source", ""))
return n > 0

